UPDATE user_secret
SET tenant_id = #{tenantId}, user_id = #{userId}, secret_type = #{secretType}, secret_value_hash = #{secretValueHash}, salt = #{salt}, expire_time = #{expireTime}, status = #{status}, metadata = #{metadata}
WHERE id = #{id} AND deleted = 0

UPDATE user_secret
SET status = 'disabled'
WHERE user_id = #{userId}
  AND secret_type = #{secretType}
  AND status = 'active'
  AND deleted = 0
